   135→
   136→  const formatDate = (d: string) => {
   137→    const date = new Date(d + 'T00:00:00');
   138→    return date.toLocaleDateString('de-AT', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
   139→  };
   140→
   141→  return (
   142→    <div ref={pageRef} className="space-y-6">
   143→      <div className="flex items-center justify-between gap-2">
   144→        <div className="min-w-0">
   145→          <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f]">Auswertung</h1>
   146→          <p className="text-xs sm:text-sm text-gray-500 truncate">{exercise.name} — {formatDate(exercise.date)}</p>
   147→        </div>
   148→        <div className="flex items-center gap-2 flex-shrink-0" data-no-export="true">
   149→          <button
   150→            onClick={downloadFullPage}
   151→            disabled={exporting}
   152→            className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm disabled:opacity-50"
   153→          >
   154→            {exporting ? 'Exportieren...' : 'Download Auswertung'}
   155→          </button>
   156→          <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm">
   157→            Zurück
   158→          </Link>
   159→        </div>
   160→      </div>
   161→
   162→      {stats && (
   163→        <>
   164→          {/* Summary cards */}
   165→          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3">
   166→            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   167→              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalParticipants}</div>
   168→              <div className="text-xs sm:text-sm text-gray-500">Teilnehmer</div>
   169→            </div>
   170→            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   171→              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalReports}</div>
   172→              <div className="text-xs sm:text-sm text-gray-500">Rapporte</div>
   173→            </div>
   174→            {stats.perRepeater.map((r) => (
   175→              <div key={r.short_name} className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   176→                <div className="text-xl sm:text-2xl font-bold text-gray-700">{r.count}</div>
