import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      // Map repeater_id back to blCode via current blRepSelection
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlOpCallsigns(prev => ({ ...prev, [blCode]: data.operator_callsign || '' }));
          }
        }
        return sel;
      });
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    return () => { socket.off('op_callsign_updated', handleOpCallsignUpdated); };
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repId, operator_callsign: val });
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      if (!repeaterId) return;
      const operator = await getOrCreateOperator(form.callsign, form.operator);
      if (!operator) return;

      const parsed = parseRapport(form.rapport);

      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: repeaterId,
            ...parsed,
            notes: form.notes || null,
            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
          }),
        });
        onReportCreated(report);
      } catch (err: any) {
        if (err.message?.includes('existiert') && err.data?.existing_report) {
          const existing = err.data.existing_report;
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null, bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null }),
          });
          onReportUpdated(updated);
        }
      }
    } catch {
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null }),
      });
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const domesticBlCodes = new Set(bundeslaender.filter(b => !b.is_international).map(b => b.code));

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        // Match reports by bezirk's Bundesland, only for linked repeaters
        const blBezirkCodes = new Set(blBezirke.map(b => b.code));
        const blReports = reports.filter(r => {
          if (!r.repeater_is_linked) return false;
          // Primary: match by bezirk code
          if (r.bezirk_code && blBezirkCodes.has(r.bezirk_code)) return true;
          // Fallback for null bezirk_code: use operator BL (if domestic), else repeater BL
          if (!r.bezirk_code) {
            const effectiveBl = domesticBlCodes.has(r.bundesland_code) ? r.bundesland_code : r.repeater_bundesland_code;
            return effectiveBl === bl.code;
          }
          return false;
        });
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-xs sm:text-sm truncate">OE{parseInt(bl.code)} {bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
                <button
                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
                >
                  + Umsetzer
                </button>
                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufz."
                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                {addRepBl === bl.code && (
                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
                    <input
                      type="text"
                      value={newRepName}
                      onChange={e => setNewRepName(e.target.value)}
                      placeholder="Name"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      autoFocus
                    />
                    <input
                      type="text"
                      value={newRepFreq}
                      onChange={e => setNewRepFreq(e.target.value)}
                      placeholder="MHz"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      value={newRepCallsign}
                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                      placeholder="Rufz."
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                      onClick={() => addRepeater(bl.code)}
                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                    >
                      OK
                    </button>
                    <button
                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                      className="text-gray-400 hover:text-gray-600 text-xs"
                    >
                      Abbrechen
                    </button>
                  </div>
                )}
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })}
                  {/* Sonstige — reports without matching bezirk + entry form */}
                  {(() => {
                    const bzCodes = new Set(blBezirke.map(b => b.code));
                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                    return (
                      <BezirkRow
                        bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                        reports={unassigned}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit('??', repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })()}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  availableBezirke: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, availableBezirke, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    if (!repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={6} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 text-blue-600 text-xs cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.repeater_name || ''}</td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      // Map repeater_id back to blCode via current blRepSelection
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlOpCallsigns(prev => ({ ...prev, [blCode]: data.operator_callsign || '' }));
          }
        }
        return sel;
      });
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    return () => { socket.off('op_callsign_updated', handleOpCallsignUpdated); };
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repId, operator_callsign: val });
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      if (!repeaterId) return;
      const operator = await getOrCreateOperator(form.callsign, form.operator);
      if (!operator) return;

      const parsed = parseRapport(form.rapport);

      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: repeaterId,
            ...parsed,
            notes: form.notes || null,
            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
            suffix: form.suffix || null,
          }),
        });
        onReportCreated(report);
      } catch (err: any) {
        if (err.message?.includes('existiert') && err.data?.existing_report) {
          const existing = err.data.existing_report;
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null, bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null, suffix: form.suffix || null }),
          });
          onReportUpdated(updated);
        }
      }
    } catch {
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
      suffix: report.suffix || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null, suffix: editForm.suffix || null }),
      });
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const domesticBlCodes = new Set(bundeslaender.filter(b => !b.is_international).map(b => b.code));

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        // Match reports by bezirk's Bundesland, only for linked repeaters
        const blBezirkCodes = new Set(blBezirke.map(b => b.code));
        const blReports = reports.filter(r => {
          if (!r.repeater_is_linked) return false;
          // Primary: match by bezirk code
          if (r.bezirk_code && blBezirkCodes.has(r.bezirk_code)) return true;
          // Fallback for null bezirk_code: use operator BL (if domestic), else repeater BL
          if (!r.bezirk_code) {
            const effectiveBl = domesticBlCodes.has(r.bundesland_code) ? r.bundesland_code : r.repeater_bundesland_code;
            return effectiveBl === bl.code;
          }
          return false;
        });
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-xs sm:text-sm truncate">OE{parseInt(bl.code)} {bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
                <button
                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
                >
                  + Umsetzer
                </button>
                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufz."
                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                {addRepBl === bl.code && (
                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
                    <input
                      type="text"
                      value={newRepName}
                      onChange={e => setNewRepName(e.target.value)}
                      placeholder="Name"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      autoFocus
                    />
                    <input
                      type="text"
                      value={newRepFreq}
                      onChange={e => setNewRepFreq(e.target.value)}
                      placeholder="MHz"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      value={newRepCallsign}
                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                      placeholder="Rufz."
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                      onClick={() => addRepeater(bl.code)}
                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                    >
                      OK
                    </button>
                    <button
                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                      className="text-gray-400 hover:text-gray-600 text-xs"
                    >
                      Abbrechen
                    </button>
                  </div>
                )}
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })}
                  {/* Sonstige — reports without matching bezirk + entry form */}
                  {(() => {
                    const bzCodes = new Set(blBezirke.map(b => b.code));
                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                    return (
                      <BezirkRow
                        bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                        reports={unassigned}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit('??', repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })()}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  availableBezirke: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, availableBezirke, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    if (!repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={6} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 text-blue-600 text-xs cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.repeater_name || ''}</td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      // Map repeater_id back to blCode via current blRepSelection
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlOpCallsigns(prev => ({ ...prev, [blCode]: data.operator_callsign || '' }));
          }
        }
        return sel;
      });
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    return () => { socket.off('op_callsign_updated', handleOpCallsignUpdated); };
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repId, operator_callsign: val });
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      if (!repeaterId) return;
      const operator = await getOrCreateOperator(form.callsign, form.operator);
      if (!operator) return;

      const parsed = parseRapport(form.rapport);

      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: repeaterId,
            ...parsed,
            notes: form.notes || null,
            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
            suffix: form.suffix || null,
          }),
        });
        onReportCreated(report);
      } catch (err: any) {
        if (err.message?.includes('existiert') && err.data?.existing_report) {
          const existing = err.data.existing_report;
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null, bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null, suffix: form.suffix || null }),
          });
          onReportUpdated(updated);
        }
      }
    } catch {
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
      suffix: report.suffix || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null, suffix: editForm.suffix || null }),
      });
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const domesticBlCodes = new Set(bundeslaender.filter(b => !b.is_international).map(b => b.code));

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        // Match reports by bezirk's Bundesland, only for linked repeaters
        const blBezirkCodes = new Set(blBezirke.map(b => b.code));
        const blReports = reports.filter(r => {
          if (!r.repeater_is_linked) return false;
          // Primary: match by bezirk code
          if (r.bezirk_code && blBezirkCodes.has(r.bezirk_code)) return true;
          // Fallback for null bezirk_code: use operator BL (if domestic), else repeater BL
          if (!r.bezirk_code) {
            const effectiveBl = domesticBlCodes.has(r.bundesland_code) ? r.bundesland_code : r.repeater_bundesland_code;
            return effectiveBl === bl.code;
          }
          return false;
        });
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-xs sm:text-sm truncate">OE{parseInt(bl.code)} {bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
                <button
                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
                >
                  + Umsetzer
                </button>
                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufz."
                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                {addRepBl === bl.code && (
                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
                    <input
                      type="text"
                      value={newRepName}
                      onChange={e => setNewRepName(e.target.value)}
                      placeholder="Name"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      autoFocus
                    />
                    <input
                      type="text"
                      value={newRepFreq}
                      onChange={e => setNewRepFreq(e.target.value)}
                      placeholder="MHz"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      value={newRepCallsign}
                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                      placeholder="Rufz."
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                      onClick={() => addRepeater(bl.code)}
                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                    >
                      OK
                    </button>
                    <button
                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                      className="text-gray-400 hover:text-gray-600 text-xs"
                    >
                      Abbrechen
                    </button>
                  </div>
                )}
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })}
                  {/* Sonstige — reports without matching bezirk + entry form */}
                  {(() => {
                    const bzCodes = new Set(blBezirke.map(b => b.code));
                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                    return (
                      <BezirkRow
                        bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                        reports={unassigned}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit('??', repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })()}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  availableBezirke: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, availableBezirke, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    if (!repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={6} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 text-blue-600 text-xs cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.repeater_name || ''}</td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      // Map repeater_id back to blCode via current blRepSelection
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlOpCallsigns(prev => ({ ...prev, [blCode]: data.operator_callsign || '' }));
          }
        }
        return sel;
      });
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    return () => { socket.off('op_callsign_updated', handleOpCallsignUpdated); };
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repId, operator_callsign: val });
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      if (!repeaterId) return;
      const operator = await getOrCreateOperator(form.callsign, form.operator);
      if (!operator) return;

      const parsed = parseRapport(form.rapport);

      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: repeaterId,
            ...parsed,
            notes: form.notes || null,
            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
            suffix: form.suffix || null,
          }),
        });
        onReportCreated(report);
      } catch (err: any) {
        if (err.message?.includes('existiert') && err.data?.existing_report) {
          const existing = err.data.existing_report;
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null, bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null, suffix: form.suffix || null }),
          });
          onReportUpdated(updated);
        }
      }
    } catch {
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
      suffix: report.suffix || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null, suffix: editForm.suffix || null }),
      });
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const domesticBlCodes = new Set(bundeslaender.filter(b => !b.is_international).map(b => b.code));

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        // Match reports by bezirk's Bundesland, only for linked repeaters
        const blBezirkCodes = new Set(blBezirke.map(b => b.code));
        const blReports = reports.filter(r => {
          if (!r.repeater_is_linked) return false;
          // Primary: match by bezirk code
          if (r.bezirk_code && blBezirkCodes.has(r.bezirk_code)) return true;
          // Fallback for null bezirk_code: use operator BL (if domestic), else repeater BL
          if (!r.bezirk_code) {
            const effectiveBl = domesticBlCodes.has(r.bundesland_code) ? r.bundesland_code : r.repeater_bundesland_code;
            return effectiveBl === bl.code;
          }
          return false;
        });
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-xs sm:text-sm truncate">OE{parseInt(bl.code)} {bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
                <button
                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
                >
                  + Umsetzer
                </button>
                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufz."
                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                {addRepBl === bl.code && (
                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
                    <input
                      type="text"
                      value={newRepName}
                      onChange={e => setNewRepName(e.target.value)}
                      placeholder="Name"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      autoFocus
                    />
                    <input
                      type="text"
                      value={newRepFreq}
                      onChange={e => setNewRepFreq(e.target.value)}
                      placeholder="MHz"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      value={newRepCallsign}
                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                      placeholder="Rufz."
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                      onClick={() => addRepeater(bl.code)}
                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                    >
                      OK
                    </button>
                    <button
                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                      className="text-gray-400 hover:text-gray-600 text-xs"
                    >
                      Abbrechen
                    </button>
                  </div>
                )}
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })}
                  {/* Sonstige — reports without matching bezirk + entry form */}
                  {(() => {
                    const bzCodes = new Set(blBezirke.map(b => b.code));
                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                    return (
                      <BezirkRow
                        bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                        reports={unassigned}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit('??', repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })()}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  availableBezirke: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, availableBezirke, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    if (!repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={6} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 text-blue-600 text-xs cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.repeater_name || ''}</td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      // Map repeater_id back to blCode via current blRepSelection
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlOpCallsigns(prev => ({ ...prev, [blCode]: data.operator_callsign || '' }));
          }
        }
        return sel;
      });
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    return () => { socket.off('op_callsign_updated', handleOpCallsignUpdated); };
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repId, operator_callsign: val });
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      if (!repeaterId) return;
      const operator = await getOrCreateOperator(form.callsign, form.operator);
      if (!operator) return;

      const parsed = parseRapport(form.rapport);

      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: repeaterId,
            ...parsed,
            notes: form.notes || null,
            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
            suffix: form.suffix || null,
          }),
        });
        onReportCreated(report);
      } catch (err: any) {
        if (err.message?.includes('existiert') && err.data?.existing_report) {
          const existing = err.data.existing_report;
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null, bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null, suffix: form.suffix || null }),
          });
          onReportUpdated(updated);
        }
      }
    } catch {
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
      suffix: report.suffix || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null, suffix: editForm.suffix || null }),
      });
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const domesticBlCodes = new Set(bundeslaender.filter(b => !b.is_international).map(b => b.code));

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        // Match reports by bezirk's Bundesland, only for linked repeaters
        const blBezirkCodes = new Set(blBezirke.map(b => b.code));
        const blReports = reports.filter(r => {
          if (!r.repeater_is_linked) return false;
          // Primary: match by bezirk code
          if (r.bezirk_code && blBezirkCodes.has(r.bezirk_code)) return true;
          // Fallback for null bezirk_code: use operator BL (if domestic), else repeater BL
          if (!r.bezirk_code) {
            const effectiveBl = domesticBlCodes.has(r.bundesland_code) ? r.bundesland_code : r.repeater_bundesland_code;
            return effectiveBl === bl.code;
          }
          return false;
        });
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-xs sm:text-sm truncate">OE{parseInt(bl.code)} {bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
                <button
                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
                >
                  + Umsetzer
                </button>
                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufz."
                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                {addRepBl === bl.code && (
                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
                    <input
                      type="text"
                      value={newRepName}
                      onChange={e => setNewRepName(e.target.value)}
                      placeholder="Name"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      autoFocus
                    />
                    <input
                      type="text"
                      value={newRepFreq}
                      onChange={e => setNewRepFreq(e.target.value)}
                      placeholder="MHz"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      value={newRepCallsign}
                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                      placeholder="Rufz."
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                      onClick={() => addRepeater(bl.code)}
                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                    >
                      OK
                    </button>
                    <button
                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                      className="text-gray-400 hover:text-gray-600 text-xs"
                    >
                      Abbrechen
                    </button>
                  </div>
                )}
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })}
                  {/* Sonstige — reports without matching bezirk + entry form */}
                  {(() => {
                    const bzCodes = new Set(blBezirke.map(b => b.code));
                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                    return (
                      <BezirkRow
                        bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                        reports={unassigned}
                        availableBezirke={blBezirke}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit('??', repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })()}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  availableBezirke: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, availableBezirke, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    if (!repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={6} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}{r.suffix || ''}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 text-blue-600 text-xs cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.repeater_name || ''}</td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../services/api';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement,
  ArcElement, PointElement, LineElement,
  Title, Tooltip, Legend,
} from 'chart.js';
import { Bar, Pie } from 'react-chartjs-2';
import { toPng } from 'html-to-image';
import AustriaMap from '../components/AustriaMap';
import type { BezirkStat, Stats } from '../types/stats';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, PointElement, LineElement, Title, Tooltip, Legend);

export default function ReportsPage() {
  const { id } = useParams<{ id: string }>();
  const [exercise, setExercise] = useState<any>(null);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [showParticipants, setShowParticipants] = useState(true);
  const barChartRef = useRef<any>(null);
  const pieChartRef = useRef<any>(null);
  const barCardRef = useRef<HTMLDivElement>(null);
  const pieCardRef = useRef<HTMLDivElement>(null);
  const mapCardRef = useRef<HTMLDivElement>(null);
  const pageRef = useRef<HTMLDivElement>(null);
  const [exporting, setExporting] = useState(false);

  const createExportHeader = () => {
    const header = document.createElement('div');
    header.setAttribute('data-export-inject', 'true');
    header.style.cssText = 'display:flex;align-items:center;gap:12px;padding:16px 24px;background:#1e3a5f;border-radius:8px;margin-bottom:16px;';
    const img = document.createElement('img');
    img.src = '/bosarsa.jpeg';
    img.style.cssText = 'height:36px;border-radius:4px;';
    header.appendChild(img);
    const text = document.createElement('div');
    const title = document.createElement('div');
    title.textContent = 'BOS-ARSA Log';
    title.style.cssText = 'font-size:16px;font-weight:bold;color:#ffffff;letter-spacing:0.5px;';
    text.appendChild(title);
    const sub = document.createElement('div');
    sub.textContent = 'Im Sinne der Sicherheit';
    sub.style.cssText = 'font-size:10px;color:#93c5fd;letter-spacing:1px;';
    text.appendChild(sub);
    header.appendChild(text);
    return header;
  };

  const createExportFooter = () => {
    const footer = document.createElement('div');
    footer.setAttribute('data-export-inject', 'true');
    footer.style.cssText = 'text-align:center;padding:12px 0;margin-top:16px;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;';
    footer.textContent = 'oeradio.at  \u00B7  bosarsa.oeradio.at';
    return footer;
  };

  const downloadChart = async (cardRef: React.RefObject<HTMLDivElement | null>, filename: string) => {
    if (!cardRef.current || !exercise) return;
    setExporting(true);
    const header = createExportHeader();
    const footer = createExportFooter();
    // Wrap the card temporarily
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'padding:24px;background:#f3f4f6;';
    const parent = cardRef.current.parentNode!;
    const next = cardRef.current.nextSibling;
    parent.insertBefore(wrapper, cardRef.current);
    wrapper.appendChild(header);
    wrapper.appendChild(cardRef.current);
    wrapper.appendChild(footer);
    try {
      const url = await toPng(wrapper, { backgroundColor: '#f3f4f6', pixelRatio: 2 });
      const link = document.createElement('a');
      link.download = filename;
      link.href = url;
      link.click();
    } catch {} finally {
      // Move card back to original position
      if (next) parent.insertBefore(cardRef.current, next); else parent.appendChild(cardRef.current);
      wrapper.remove();
      setExporting(false);
    }
  };

  const downloadFullPage = async () => {
    if (!exercise) return;
    setExporting(true);
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/v1/pdf/exercises/${id}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (!res.ok) throw new Error();
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `BOS-ARSA_Auswertung_${exercise.date}.pdf`;
      link.click();
      URL.revokeObjectURL(url);
    } catch {} finally {
      setExporting(false);
    }
  };

  useEffect(() => {
    if (!id) return;
    Promise.all([
      apiFetch(`/api/v1/exercises/${id}`),
      apiFetch(`/api/v1/exercises/${id}/stats`),
    ]).then(([ex, st]) => {
      setExercise(ex);
      setStats(st);
    }).catch(() => {}).finally(() => setLoading(false));
  }, [id]);

  if (loading) return <p className="text-gray-500">Laden...</p>;
  if (!exercise) return <p className="text-red-500">Nicht gefunden</p>;

  // Group bezirk stats by Bundesland
  const byBl: Record<string, { name: string; bezirke: BezirkStat[]; totalParticipants: number; totalReports: number }> = {};
  if (stats) {
    for (const bz of stats.bezirkStats) {
      if (!byBl[bz.bundesland_code]) {
        byBl[bz.bundesland_code] = { name: bz.bundesland, bezirke: [], totalParticipants: 0, totalReports: 0 };
      }
      byBl[bz.bundesland_code].bezirke.push(bz);
      byBl[bz.bundesland_code].totalParticipants += bz.participants;
      byBl[bz.bundesland_code].totalReports += bz.reports;
    }
  }

  const formatDate = (d: string) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-AT', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
  };

  return (
    <div ref={pageRef} className="space-y-6">
      <div className="flex items-center justify-between gap-2">
        <div className="min-w-0">
          <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f]">Auswertung</h1>
          <p className="text-xs sm:text-sm text-gray-500 truncate">{exercise.name} — {formatDate(exercise.date)}</p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0" data-no-export="true">
          <button
            onClick={downloadFullPage}
            disabled={exporting}
            className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm disabled:opacity-50"
          >
            {exporting ? 'Exportieren...' : 'Download Auswertung'}
          </button>
          <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm">
            Zurück
          </Link>
        </div>
      </div>

      {stats && (
        <>
          {/* Summary cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3">
            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalParticipants}</div>
              <div className="text-xs sm:text-sm text-gray-500">Teilnehmer</div>
            </div>
            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalReports}</div>
              <div className="text-xs sm:text-sm text-gray-500">Rapporte</div>
            </div>
            {stats.perRepeater.map((r) => (
              <div key={r.short_name} className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
                <div className="text-xl sm:text-2xl font-bold text-gray-700">{r.count}</div>
                <div className="text-xs text-gray-500 truncate">{r.short_name}</div>
              </div>
            ))}
          </div>

          {/* Austria Map */}
          {stats.blStats.length > 0 && (
            <div ref={mapCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
              <div className="flex items-center justify-between mb-2 sm:mb-3">
                <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
                  Teilnehmer nach Bundesland / Land
                </h2>
                <button
                  onClick={() => downloadChart(mapCardRef, `BOS-ARSA_Karte_${exercise.date}.png`)}
                  className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
                  title="Karte als PNG herunterladen"
                  data-no-export="true"
                >
                  Download
                </button>
              </div>
              <AustriaMap
                data={stats.blStats.map((bl) => ({
                  code: bl.bundesland_code,
                  participants: bl.participants,
                  reports: bl.reports,
                }))}
              />
            </div>
          )}

          {/* Charts */}
          {(() => {
            // Use bezirkStats if available, otherwise fall back to blStats (Bundesland level)
            const chartData = stats.bezirkStats.length > 0
              ? stats.bezirkStats.map(bz => ({ label: `OE${parseInt(bz.bundesland_code, 10)} ${bz.bezirk_code}`, participants: bz.participants, reports: bz.reports }))
              : stats.blStats.map(bl => ({ label: `OE${parseInt(bl.bundesland_code, 10)}`, participants: bl.participants, reports: bl.reports }));
            const chartLevel = stats.bezirkStats.length > 0 ? 'Bezirk' : 'Bundesland';

            return chartData.length > 0 ? (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              {/* Bar chart: Stationen + Rapporte */}
              <div ref={barCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
                <div className="flex items-center justify-between mb-2 sm:mb-3">
                  <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
                    BOS-ARSA Übung am {new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT')}
                  </h2>
                  <button
                    onClick={() => downloadChart(barCardRef, `BOS-ARSA_Stationen_${exercise.date}.png`)}
                    className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
                    title="Grafik als PNG herunterladen"
                    data-no-export="true"
                  >
                    Download
                  </button>
                </div>
                <div className="h-48 sm:h-[350px]">
                  <Bar
                    ref={barChartRef}
                    data={{
                      labels: chartData.map(d => d.label),
                      datasets: [
                        {
                          label: 'Stationen',
                          data: chartData.map(d => d.participants),
                          backgroundColor: '#1e3a5f',
                        },
                        {
                          label: 'Rapporte',
                          data: chartData.map(d => d.reports),
                          backgroundColor: '#c8102e',
                        },
                      ],
                    }}
                    options={{
                      responsive: true,
                      maintainAspectRatio: false,
                      plugins: { legend: { position: 'bottom' } },
                      scales: {
                        x: { ticks: { maxRotation: 90, minRotation: 45, font: { size: 9 } } },
                        y: { beginAtZero: true },
                      },
                    }}
                  />
                </div>
              </div>

              {/* Pie chart: Rapporte distribution */}
              <div ref={pieCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
                <div className="flex items-center justify-between mb-2 sm:mb-3">
                  <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
                    Rapporte Verteilung nach Bundesland / Land
                  </h2>
                  <button
                    onClick={() => downloadChart(pieCardRef, `BOS-ARSA_Verteilung_${exercise.date}.png`)}
                    className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
                    title="Grafik als PNG herunterladen"
                    data-no-export="true"
                  >
                    Download
                  </button>
                </div>
                <div className="h-48 sm:h-[350px] flex items-center justify-center">
                  <Pie
                    ref={pieChartRef}
                    data={{
                      labels: chartData.filter(d => d.reports > 0).map(d => d.label),
                      datasets: [{
                        data: chartData.filter(d => d.reports > 0).map(d => d.reports),
                        backgroundColor: [
                          '#1e3a5f', '#c8102e', '#d97706', '#0d6efd', '#198754',
                          '#6f42c1', '#fd7e14', '#20c997', '#0dcaf0', '#6c757d',
                          '#2c5282', '#e8a317', '#c70039', '#4361ee', '#2d6a4f',
                          '#9b59b6', '#e67e22', '#1abc9c', '#3498db', '#95a5a6',
                        ],
                      }],
                    }}
                    options={{
                      responsive: true,
                      maintainAspectRatio: false,
                      plugins: {
                        legend: { position: 'right', labels: { font: { size: 10 } } },
                      },
                    }}
                  />
                </div>
              </div>
            </div>
          ) : null;
          })()}

          {/* Bundesland table (when no bezirk data) */}
          {stats.bezirkStats.length === 0 && stats.blStats.length > 0 && (
            <div className="bg-white rounded-xl shadow overflow-hidden">
              <div className="bg-[#1e3a5f] text-white px-4 py-2 text-sm font-semibold">
                Teilnehmer nach Bundesland / Land
              </div>
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                    <th className="px-4 py-2">Bundesland</th>
                    <th className="px-4 py-2 text-right w-28">Teilnehmer</th>
                    <th className="px-4 py-2 text-right w-28">Rapporte</th>
                  </tr>
                </thead>
                <tbody>
                  {stats.blStats.map(bl => (
                    <tr key={bl.bundesland_code} className="border-t hover:bg-blue-50">
                      <td className="px-4 py-1.5 font-medium">{bl.bundesland}</td>
                      <td className="px-4 py-1.5 text-right">{bl.participants}</td>
                      <td className="px-4 py-1.5 text-right">{bl.reports}</td>
                    </tr>
                  ))}
                  <tr className="bg-[#1e3a5f] text-white font-bold">
                    <td className="px-4 py-2">Gesamt</td>
                    <td className="px-4 py-2 text-right">{stats.totalParticipants}</td>
                    <td className="px-4 py-2 text-right">{stats.totalReports}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          )}

          {/* Bezirk/Bundesland table */}
          {stats.bezirkStats.length > 0 && (
            <div className="bg-white rounded-xl shadow overflow-hidden">
              <div className="bg-[#1e3a5f] text-white px-2 sm:px-4 py-2 text-xs sm:text-sm font-semibold">
                Nebenstationen nach Bezirk
              </div>
              <div className="overflow-x-auto">
              <table className="w-full text-xs sm:text-sm min-w-[360px]">
                <thead>
                  <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                    <th className="px-2 sm:px-4 py-2">Bundesland / Bezirk</th>
                    <th className="px-2 sm:px-4 py-2 text-right w-16 sm:w-28">Teiln.</th>
                    <th className="px-2 sm:px-4 py-2 text-right w-16 sm:w-28">Rapp.</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(byBl).map(([blCode, bl]) => (
                    <>
                      {/* Bundesland header */}
                      <tr key={`bl-${blCode}`} className="bg-gray-50 font-medium border-t">
                        <td className="px-4 py-1.5">{bl.name}</td>
                        <td className="px-4 py-1.5 text-right font-bold">{bl.totalParticipants}</td>
                        <td className="px-4 py-1.5 text-right font-bold">{bl.totalReports}</td>
                      </tr>
                      {/* Bezirk rows */}
                      {bl.bezirke.map(bz => (
                        <tr key={bz.bezirk_code} className="border-t border-gray-100 hover:bg-blue-50">
                          <td className="px-4 py-1 pl-8">
                            <span className={`inline-block text-xs font-mono px-1.5 py-0.5 rounded text-white mr-2 ${bz.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
                              {bz.bezirk_code}
                            </span>
                            <span className="text-gray-600">{bz.bezirk_name}</span>
                          </td>
                          <td className="px-4 py-1 text-right">{bz.participants}</td>
                          <td className="px-4 py-1 text-right">{bz.reports}</td>
                        </tr>
                      ))}
                    </>
                  ))}
                  {/* Gesamt */}
                  <tr className="bg-[#1e3a5f] text-white font-bold">
                    <td className="px-4 py-2">Gesamt</td>
                    <td className="px-4 py-2 text-right">{stats.totalParticipants}</td>
                    <td className="px-4 py-2 text-right">{stats.totalReports}</td>
                  </tr>
                </tbody>
              </table>
              </div>
            </div>
          )}

          {/* Participants list */}
          <div className="bg-white rounded-xl shadow overflow-hidden">
            <div
              onClick={() => setShowParticipants(v => !v)}
              className="bg-[#1e3a5f] text-white px-4 py-2 text-sm font-semibold cursor-pointer hover:bg-[#2a4a7f] flex items-center justify-between"
            >
              <span>Teilnehmer-Liste ({stats.participants.length})</span>
              <span className="text-xs">{showParticipants ? '▼' : '▶'}</span>
            </div>
            {showParticipants && (
              <div className="overflow-x-auto">
              <table className="w-full text-xs sm:text-sm min-w-[360px]">
                <thead>
                  <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                    <th className="px-2 sm:px-4 py-2 w-8">#</th>
                    <th className="px-2 sm:px-4 py-2">Rufzeichen</th>
                    <th className="px-2 sm:px-4 py-2 hidden sm:table-cell">Name</th>
                    <th className="px-2 sm:px-4 py-2">Bezirk</th>
                    <th className="px-2 sm:px-4 py-2 hidden md:table-cell">Bundesland / Land</th>
                    <th className="px-2 sm:px-4 py-2 text-right w-16 sm:w-24">Rapp.</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {stats.participants.map((p, idx) => (
                    <tr key={p.callsign} className="hover:bg-blue-50">
                      <td className="px-2 sm:px-4 py-1 text-xs text-gray-400">{idx + 1}</td>
                      <td className="px-2 sm:px-4 py-1 font-mono font-medium">{p.callsign}</td>
                      <td className="px-2 sm:px-4 py-1 text-gray-600 hidden sm:table-cell">{p.name || ''}</td>
                      <td className="px-2 sm:px-4 py-1">
                        {p.bezirk_code && (
                          <span className="text-xs bg-gray-200 rounded px-1.5 py-0.5 font-mono">{p.bezirk_code}</span>
                        )}
                      </td>
                      <td className="px-2 sm:px-4 py-1 text-gray-600 text-xs hidden md:table-cell">{p.bundesland_name || ''}</td>
                      <td className="px-2 sm:px-4 py-1 text-right font-mono">{p.report_count}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              </div>
            )}
          </div>

          {/* Export buttons */}
          <div className="bg-white rounded-xl shadow p-4" data-no-export="true">
            <h2 className="text-sm font-semibold text-[#1e3a5f] mb-3">Export</h2>
            <div className="flex flex-wrap gap-3">
              <button
                onClick={downloadFullPage}
                disabled={exporting}
                className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-4 py-2 rounded text-sm font-medium disabled:opacity-50"
              >
                {exporting ? 'Exportieren...' : 'PDF — Download Auswertung'}
              </button>
              {exercise.oe_link_enabled !== 0 && (
                <a
                  href={`/api/v1/export/exercises/${id}/bund`}
                  className="bg-red-100 hover:bg-red-200 text-red-800 px-4 py-2 rounded text-sm font-medium"
                  target="_blank"
                >
                  TXT — OE-Link
                </a>
              )}
              <a
                href={`/api/v1/export/exercises/${id}/land`}
                className="bg-red-100 hover:bg-red-200 text-red-800 px-4 py-2 rounded text-sm font-medium"
                target="_blank"
              >
                TXT — Frequenzen
              </a>
              <a
                href={`/api/v1/export/exercises/${id}/combined`}
                className="bg-red-100 hover:bg-red-200 text-red-800 px-4 py-2 rounded text-sm font-medium"
                target="_blank"
              >
                TXT — Kombiniert
              </a>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { apiFetch } from '../services/api';
import { EXERCISE_TYPES, getShortLabel } from '../constants/exerciseTypes';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement,
  ArcElement, PointElement, LineElement,
  Title, Tooltip, Legend,
} from 'chart.js';
import { Bar, Pie } from 'react-chartjs-2';
import { toPng } from 'html-to-image';
import AustriaMap from '../components/AustriaMap';
import type { BezirkStat, Stats } from '../types/stats';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, PointElement, LineElement, Title, Tooltip, Legend);

interface ExerciseSummary {
  id: string;
  date: string;
  name: string;
  exercise_type: string | null;
  participant_count: number;
  report_count: number;
}

interface AggregatedResponse {
  exercises: ExerciseSummary[];
  stats: Stats;
}

const PIE_COLORS = [
  '#1e3a5f', '#c8102e', '#d97706', '#0d6efd', '#198754',
  '#6f42c1', '#fd7e14', '#20c997', '#0dcaf0', '#6c757d',
  '#2c5282', '#e8a317', '#c70039', '#4361ee', '#2d6a4f',
  '#9b59b6', '#e67e22', '#1abc9c', '#3498db', '#95a5a6',
];

function formatDateDE(d: string) {
  const date = new Date(d + 'T00:00:00');
  return date.toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

function toISO(d: Date) {
  return d.toISOString().slice(0, 10);
}

export default function AggregatedReportsPage() {
  const now = new Date();
  const year = now.getFullYear();

  const [from, setFrom] = useState(() => toISO(new Date(year, 0, 1)));
  const [to, setTo] = useState(() => toISO(new Date(year, 11, 31)));
  const [data, setData] = useState<AggregatedResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [showExercises, setShowExercises] = useState(false);
  const [showParticipants, setShowParticipants] = useState(true);
  const [exporting, setExporting] = useState(false);
  const [selectedTypes, setSelectedTypes] = useState<Set<string>>(new Set());

  const barChartRef = useRef<any>(null);
  const pieChartRef = useRef<any>(null);
  const barCardRef = useRef<HTMLDivElement>(null);
  const pieCardRef = useRef<HTMLDivElement>(null);
  const mapCardRef = useRef<HTMLDivElement>(null);
  const pageRef = useRef<HTMLDivElement>(null);

  const fetchStats = (f: string, t: string, types?: Set<string>) => {
    setLoading(true);
    const typesParam = types && types.size > 0 ? `&types=${Array.from(types).map(encodeURIComponent).join(',')}` : '';
    apiFetch(`/api/v1/reports/stats?from=${f}&to=${t}${typesParam}`)
      .then((res) => setData(res))
      .catch(() => setData(null))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchStats(from, to, selectedTypes);
  }, []);

  const applyRange = (f: string, t: string) => {
    setFrom(f);
    setTo(t);
    fetchStats(f, t, selectedTypes);
  };

  const applyQuarter = (q: number) => {
    const start = new Date(year, (q - 1) * 3, 1);
    const end = new Date(year, q * 3, 0);
    applyRange(toISO(start), toISO(end));
  };

  const applyYear = () => {
    applyRange(toISO(new Date(year, 0, 1)), toISO(new Date(year, 11, 31)));
  };

  const handleFromChange = (v: string) => {
    setFrom(v);
    fetchStats(v, to, selectedTypes);
  };

  const handleToChange = (v: string) => {
    setTo(v);
    fetchStats(from, v, selectedTypes);
  };

  const toggleType = (type: string) => {
    setSelectedTypes(prev => {
      const next = new Set(prev);
      if (next.has(type)) next.delete(type);
      else next.add(type);
      fetchStats(from, to, next);
      return next;
    });
  };

  const createExportHeader = () => {
    const header = document.createElement('div');
    header.setAttribute('data-export-inject', 'true');
    header.style.cssText = 'display:flex;align-items:center;gap:12px;padding:16px 24px;background:#1e3a5f;border-radius:8px;margin-bottom:16px;';
    const img = document.createElement('img');
    img.src = '/bosarsa.jpeg';
    img.style.cssText = 'height:36px;border-radius:4px;';
    header.appendChild(img);
    const text = document.createElement('div');
    const title = document.createElement('div');
    title.textContent = 'BOS-ARSA Log';
    title.style.cssText = 'font-size:16px;font-weight:bold;color:#ffffff;letter-spacing:0.5px;';
    text.appendChild(title);
    const sub = document.createElement('div');
    sub.textContent = 'Im Sinne der Sicherheit';
    sub.style.cssText = 'font-size:10px;color:#93c5fd;letter-spacing:1px;';
    text.appendChild(sub);
    header.appendChild(text);
    return header;
  };

  const createExportFooter = () => {
    const footer = document.createElement('div');
    footer.setAttribute('data-export-inject', 'true');
    footer.style.cssText = 'text-align:center;padding:12px 0;margin-top:16px;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;';
    footer.textContent = 'oeradio.at  \u00B7  bosarsa.oeradio.at';
    return footer;
  };

  const downloadChart = async (cardRef: React.RefObject<HTMLDivElement | null>, filename: string) => {
    if (!cardRef.current) return;
    setExporting(true);
    const header = createExportHeader();
    const footer = createExportFooter();
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'padding:24px;background:#f3f4f6;';
    const parent = cardRef.current.parentNode!;
    const next = cardRef.current.nextSibling;
    parent.insertBefore(wrapper, cardRef.current);
    wrapper.appendChild(header);
    wrapper.appendChild(cardRef.current);
    wrapper.appendChild(footer);
    try {
      const url = await toPng(wrapper, { backgroundColor: '#f3f4f6', pixelRatio: 2 });
      const link = document.createElement('a');
      link.download = filename;
      link.href = url;
      link.click();
    } catch {} finally {
      if (next) parent.insertBefore(cardRef.current, next); else parent.appendChild(cardRef.current);
      wrapper.remove();
      setExporting(false);
    }
  };

  const downloadFullPage = async () => {
    setExporting(true);
    try {
      const token = localStorage.getItem('token');
      const typesParam = selectedTypes.size > 0 ? `&types=${Array.from(selectedTypes).map(encodeURIComponent).join(',')}` : '';
      const res = await fetch(`/api/v1/pdf/reports?from=${from}&to=${to}${typesParam}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (!res.ok) throw new Error();
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `BOS-ARSA_Auswertung_${from}_${to}.pdf`;
      link.click();
      URL.revokeObjectURL(url);
    } catch {} finally {
      setExporting(false);
    }
  };

  const stats = data?.stats ?? null;
  const exercises = data?.exercises ?? [];

  // Group bezirk stats by Bundesland
  const byBl: Record<string, { name: string; bezirke: BezirkStat[]; totalParticipants: number; totalReports: number }> = {};
  if (stats) {
    for (const bz of stats.bezirkStats) {
      if (!byBl[bz.bundesland_code]) {
        byBl[bz.bundesland_code] = { name: bz.bundesland, bezirke: [], totalParticipants: 0, totalReports: 0 };
      }
      byBl[bz.bundesland_code].bezirke.push(bz);
      byBl[bz.bundesland_code].totalParticipants += bz.participants;
      byBl[bz.bundesland_code].totalReports += bz.reports;
    }
  }

  const avgParticipants = exercises.length > 0
    ? Math.round((stats?.totalParticipants ?? 0) / exercises.length * 10) / 10
    : 0;

  return (
    <div ref={pageRef} className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <div className="min-w-0">
          <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f]">Auswertung</h1>
          {exercises.length > 0 && (
            <p className="text-xs sm:text-sm text-gray-500">
              {formatDateDE(from)} – {formatDateDE(to)} · {exercises.length} Übung{exercises.length !== 1 ? 'en' : ''}
            </p>
          )}
        </div>
        <div className="flex items-center gap-2 flex-shrink-0" data-no-export="true">
          {stats && exercises.length > 0 && (
            <>
              <button
                onClick={async () => {
                  try {
                    const token = localStorage.getItem('token');
                    const res = await fetch(`/api/v1/reports/adif?from=${from}&to=${to}`, {
                      headers: token ? { Authorization: `Bearer ${token}` } : {},
                    });
                    if (!res.ok) throw new Error();
                    const blob = await res.blob();
                    const url = URL.createObjectURL(blob);
                    const link = document.createElement('a');
                    link.href = url;
                    link.download = `BOS-ARSA_QSOs_${from}_${to}.adi`;
                    link.click();
                    URL.revokeObjectURL(url);
                  } catch {}
                }}
                className="bg-red-700 hover:bg-red-800 text-white px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm"
                title="ADIF-Datei für QRZ.com, LOTW etc."
              >
                Download ADIF
              </button>
              <button
                onClick={downloadFullPage}
                disabled={exporting}
                className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm disabled:opacity-50"
              >
                {exporting ? '...' : 'Download Auswertung'}
              </button>
            </>
          )}
        </div>
      </div>

      {/* Date range selector */}
      <div className="bg-white rounded-xl shadow p-3 sm:p-4" data-no-export="true">
        <div className="flex flex-wrap gap-2 mb-3">
          {[1, 2, 3, 4].map((q) => (
            <button
              key={q}
              onClick={() => applyQuarter(q)}
              className="bg-gray-100 hover:bg-blue-100 text-gray-700 hover:text-[#1e3a5f] px-3 py-1.5 rounded text-sm font-medium"
            >
              Q{q}
            </button>
          ))}
          <button
            onClick={applyYear}
            className="bg-gray-100 hover:bg-blue-100 text-gray-700 hover:text-[#1e3a5f] px-3 py-1.5 rounded text-sm font-medium"
          >
            Jahr {year}
          </button>
        </div>
        <div className="flex flex-wrap items-center gap-2 text-sm">
          <label className="text-gray-500 text-xs">Von</label>
          <input
            type="date"
            value={from}
            onChange={(e) => handleFromChange(e.target.value)}
            className="border rounded px-2 py-1 text-sm"
          />
          <label className="text-gray-500 text-xs">Bis</label>
          <input
            type="date"
            value={to}
            onChange={(e) => handleToChange(e.target.value)}
            className="border rounded px-2 py-1 text-sm"
          />
        </div>
        <div className="flex flex-wrap items-center gap-3 mt-3 pt-3 border-t border-gray-100">
          <span className="text-xs text-gray-500">Übungstyp:</span>
          {EXERCISE_TYPES.map(t => (
            <label key={t.value} className="flex items-center gap-1.5 cursor-pointer text-sm">
              <input
                type="checkbox"
                checked={selectedTypes.has(t.value)}
                onChange={() => toggleType(t.value)}
                className="w-3.5 h-3.5 accent-red-600"
              />
              <span className={selectedTypes.has(t.value) ? 'text-[#1e3a5f] font-medium' : 'text-gray-600'}>{t.short}</span>
            </label>
          ))}
          {selectedTypes.size > 0 && (
            <button
              onClick={() => { setSelectedTypes(new Set()); fetchStats(from, to, new Set()); }}
              className="text-xs text-gray-400 hover:text-gray-600"
            >
              Alle anzeigen
            </button>
          )}
        </div>
      </div>

      {loading && <p className="text-gray-500">Laden...</p>}

      {!loading && exercises.length === 0 && (
        <div className="bg-white rounded-xl shadow p-6 text-center text-gray-500">
          Keine Übungen im gewählten Zeitraum gefunden.
        </div>
      )}

      {!loading && stats && exercises.length > 0 && (
        <>
          {/* Summary cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3">
            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalParticipants}</div>
              <div className="text-xs sm:text-sm text-gray-500">Teilnehmer (gesamt)</div>
            </div>
            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalReports}</div>
              <div className="text-xs sm:text-sm text-gray-500">Rapporte</div>
            </div>
            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{exercises.length}</div>
              <div className="text-xs sm:text-sm text-gray-500">Übungen</div>
            </div>
            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
              <div className="text-2xl sm:text-3xl font-bold text-gray-700">{avgParticipants}</div>
              <div className="text-xs sm:text-sm text-gray-500">Ø Teilnehmer/Übung</div>
            </div>
          </div>

          {/* Per-repeater summary */}
          {stats.perRepeater.length > 0 && (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-2">
              {stats.perRepeater.map((r) => (
                <div key={r.short_name} className="bg-white rounded-lg shadow-sm p-2 sm:p-3 text-center">
                  <div className="text-lg sm:text-xl font-bold text-gray-700">{r.count}</div>
                  <div className="text-xs text-gray-500 truncate">{r.short_name}</div>
                </div>
              ))}
            </div>
          )}

          {/* Collapsible exercise list */}
          <div className="bg-white rounded-xl shadow overflow-hidden">
            <div
              onClick={() => setShowExercises((v) => !v)}
              className="bg-[#1e3a5f] text-white px-4 py-2 text-sm font-semibold cursor-pointer hover:bg-[#2a4a7f] flex items-center justify-between"
            >
              <span>Übungen ({exercises.length})</span>
              <span className="text-xs">{showExercises ? '\u25BC' : '\u25B6'}</span>
            </div>
            {showExercises && (
              <div className="overflow-x-auto">
                <table className="w-full text-xs sm:text-sm min-w-[360px]">
                  <thead>
                    <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                      <th className="px-2 sm:px-4 py-2">Datum</th>
                      <th className="px-2 sm:px-4 py-2 hidden sm:table-cell">Typ</th>
                      <th className="px-2 sm:px-4 py-2">Name</th>
                      <th className="px-2 sm:px-4 py-2 text-right w-20">Teiln.</th>
                      <th className="px-2 sm:px-4 py-2 text-right w-20">Rapp.</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {exercises.map((ex) => (
                      <tr key={ex.id} className="hover:bg-blue-50">
                        <td className="px-2 sm:px-4 py-1.5 font-mono text-xs">{formatDateDE(ex.date)}</td>
                        <td className="px-2 sm:px-4 py-1.5 text-xs text-gray-500 hidden sm:table-cell">{getShortLabel(ex.exercise_type || '')}</td>
                        <td className="px-2 sm:px-4 py-1.5">{ex.name}</td>
                        <td className="px-2 sm:px-4 py-1.5 text-right">{ex.participant_count}</td>
                        <td className="px-2 sm:px-4 py-1.5 text-right">{ex.report_count}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Austria Map */}
          {stats.blStats.length > 0 && (
            <div ref={mapCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
              <div className="flex items-center justify-between mb-2 sm:mb-3">
                <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
                  Teilnehmer nach Bundesland / Land
                </h2>
                <button
                  onClick={() => downloadChart(mapCardRef, `BOS-ARSA_Karte_${from}_${to}.png`)}
                  className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
                  title="Karte als PNG herunterladen"
                  data-no-export="true"
                >
                  Download
                </button>
              </div>
              <AustriaMap
                data={stats.blStats.map((bl) => ({
                  code: bl.bundesland_code,
                  participants: bl.participants,
                  reports: bl.reports,
                }))}
              />
            </div>
          )}

          {/* Charts */}
          {(() => {
            const chartData = stats.bezirkStats.length > 0
              ? stats.bezirkStats.map(bz => ({ label: `OE${parseInt(bz.bundesland_code, 10)} ${bz.bezirk_code}`, participants: bz.participants, reports: bz.reports }))
              : stats.blStats.map(bl => ({ label: `OE${parseInt(bl.bundesland_code, 10)}`, participants: bl.participants, reports: bl.reports }));

            return chartData.length > 0 ? (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {/* Bar chart */}
                <div ref={barCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
                  <div className="flex items-center justify-between mb-2 sm:mb-3">
                    <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
                      Auswertung {formatDateDE(from)} – {formatDateDE(to)}
                    </h2>
                    <button
                      onClick={() => downloadChart(barCardRef, `BOS-ARSA_Stationen_${from}_${to}.png`)}
                      className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
                      title="Grafik als PNG herunterladen"
                      data-no-export="true"
                    >
                      Download
                    </button>
                  </div>
                  <div className="h-48 sm:h-[350px]">
                    <Bar
                      ref={barChartRef}
                      data={{
                        labels: chartData.map(d => d.label),
                        datasets: [
                          {
                            label: 'Stationen',
                            data: chartData.map(d => d.participants),
                            backgroundColor: '#1e3a5f',
                          },
                          {
                            label: 'Rapporte',
                            data: chartData.map(d => d.reports),
                            backgroundColor: '#c8102e',
                          },
                        ],
                      }}
                      options={{
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { legend: { position: 'bottom' } },
                        scales: {
                          x: { ticks: { maxRotation: 90, minRotation: 45, font: { size: 9 } } },
                          y: { beginAtZero: true },
                        },
                      }}
                    />
                  </div>
                </div>

                {/* Pie chart */}
                <div ref={pieCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
                  <div className="flex items-center justify-between mb-2 sm:mb-3">
                    <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
                      Rapporte Verteilung nach Bundesland / Land
                    </h2>
                    <button
                      onClick={() => downloadChart(pieCardRef, `BOS-ARSA_Verteilung_${from}_${to}.png`)}
                      className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
                      title="Grafik als PNG herunterladen"
                      data-no-export="true"
                    >
                      Download
                    </button>
                  </div>
                  <div className="h-48 sm:h-[350px] flex items-center justify-center">
                    <Pie
                      ref={pieChartRef}
                      data={{
                        labels: chartData.filter(d => d.reports > 0).map(d => d.label),
                        datasets: [{
                          data: chartData.filter(d => d.reports > 0).map(d => d.reports),
                          backgroundColor: PIE_COLORS,
                        }],
                      }}
                      options={{
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                          legend: { position: 'right', labels: { font: { size: 10 } } },
                        },
                      }}
                    />
                  </div>
                </div>
              </div>
            ) : null;
          })()}

          {/* Bundesland table (when no bezirk data) */}
          {stats.bezirkStats.length === 0 && stats.blStats.length > 0 && (
            <div className="bg-white rounded-xl shadow overflow-hidden">
              <div className="bg-[#1e3a5f] text-white px-4 py-2 text-sm font-semibold">
                Teilnehmer nach Bundesland / Land
              </div>
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                    <th className="px-4 py-2">Bundesland</th>
                    <th className="px-4 py-2 text-right w-28">Teilnehmer</th>
                    <th className="px-4 py-2 text-right w-28">Rapporte</th>
                  </tr>
                </thead>
                <tbody>
                  {stats.blStats.map(bl => (
                    <tr key={bl.bundesland_code} className="border-t hover:bg-blue-50">
                      <td className="px-4 py-1.5 font-medium">{bl.bundesland}</td>
                      <td className="px-4 py-1.5 text-right">{bl.participants}</td>
                      <td className="px-4 py-1.5 text-right">{bl.reports}</td>
                    </tr>
                  ))}
                  <tr className="bg-[#1e3a5f] text-white font-bold">
                    <td className="px-4 py-2">Gesamt</td>
                    <td className="px-4 py-2 text-right">{stats.totalParticipants}</td>
                    <td className="px-4 py-2 text-right">{stats.totalReports}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          )}

          {/* Bezirk/Bundesland table */}
          {stats.bezirkStats.length > 0 && (
            <div className="bg-white rounded-xl shadow overflow-hidden">
              <div className="bg-[#1e3a5f] text-white px-2 sm:px-4 py-2 text-xs sm:text-sm font-semibold">
                Nebenstationen nach Bezirk
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-xs sm:text-sm min-w-[360px]">
                  <thead>
                    <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                      <th className="px-2 sm:px-4 py-2">Bundesland / Bezirk</th>
                      <th className="px-2 sm:px-4 py-2 text-right w-16 sm:w-28">Teiln.</th>
                      <th className="px-2 sm:px-4 py-2 text-right w-16 sm:w-28">Rapp.</th>
                    </tr>
                  </thead>
                  <tbody>
                    {Object.entries(byBl).map(([blCode, bl]) => (
                      <>
                        <tr key={`bl-${blCode}`} className="bg-gray-50 font-medium border-t">
                          <td className="px-4 py-1.5">{bl.name}</td>
                          <td className="px-4 py-1.5 text-right font-bold">{bl.totalParticipants}</td>
                          <td className="px-4 py-1.5 text-right font-bold">{bl.totalReports}</td>
                        </tr>
                        {bl.bezirke.map(bz => (
                          <tr key={bz.bezirk_code} className="border-t border-gray-100 hover:bg-blue-50">
                            <td className="px-4 py-1 pl-8">
                              <span className={`inline-block text-xs font-mono px-1.5 py-0.5 rounded text-white mr-2 ${bz.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
                                {bz.bezirk_code}
                              </span>
                              <span className="text-gray-600">{bz.bezirk_name}</span>
                            </td>
                            <td className="px-4 py-1 text-right">{bz.participants}</td>
                            <td className="px-4 py-1 text-right">{bz.reports}</td>
                          </tr>
                        ))}
                      </>
                    ))}
                    <tr className="bg-[#1e3a5f] text-white font-bold">
                      <td className="px-4 py-2">Gesamt</td>
                      <td className="px-4 py-2 text-right">{stats.totalParticipants}</td>
                      <td className="px-4 py-2 text-right">{stats.totalReports}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Participants list */}
          <div className="bg-white rounded-xl shadow overflow-hidden">
            <div
              onClick={() => setShowParticipants(v => !v)}
              className="bg-[#1e3a5f] text-white px-4 py-2 text-sm font-semibold cursor-pointer hover:bg-[#2a4a7f] flex items-center justify-between"
            >
              <span>Teilnehmer-Liste ({stats.participants.length})</span>
              <span className="text-xs">{showParticipants ? '\u25BC' : '\u25B6'}</span>
            </div>
            {showParticipants && (
              <div className="overflow-x-auto">
                <table className="w-full text-xs sm:text-sm min-w-[360px]">
                  <thead>
                    <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                      <th className="px-2 sm:px-4 py-2 w-8">#</th>
                      <th className="px-2 sm:px-4 py-2">Rufzeichen</th>
                      <th className="px-2 sm:px-4 py-2 hidden sm:table-cell">Name</th>
                      <th className="px-2 sm:px-4 py-2">Bezirk</th>
                      <th className="px-2 sm:px-4 py-2 hidden md:table-cell">Bundesland / Land</th>
                      <th className="px-2 sm:px-4 py-2 text-right w-16 sm:w-24">Rapp.</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {stats.participants.map((p, idx) => (
                      <tr key={p.callsign} className="hover:bg-blue-50">
                        <td className="px-2 sm:px-4 py-1 text-xs text-gray-400">{idx + 1}</td>
                        <td className="px-2 sm:px-4 py-1 font-mono font-medium">{p.callsign}</td>
                        <td className="px-2 sm:px-4 py-1 text-gray-600 hidden sm:table-cell">{p.name || ''}</td>
                        <td className="px-2 sm:px-4 py-1">
                          {p.bezirk_code && (
                            <span className="text-xs bg-gray-200 rounded px-1.5 py-0.5 font-mono">{p.bezirk_code}</span>
                          )}
                        </td>
                        <td className="px-2 sm:px-4 py-1 text-gray-600 text-xs hidden md:table-cell">{p.bundesland_name || ''}</td>
                        <td className="px-2 sm:px-4 py-1 text-right font-mono">{p.report_count}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Export section */}
          <div className="bg-white rounded-xl shadow p-4" data-no-export="true">
            <h2 className="text-sm font-semibold text-[#1e3a5f] mb-3">Export</h2>
            <div className="flex flex-wrap gap-3">
              <button
                onClick={downloadFullPage}
                disabled={exporting}
                className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-4 py-2 rounded text-sm font-medium disabled:opacity-50"
              >
                {exporting ? 'Exportieren...' : 'Download Auswertung'}
              </button>
              <button
                onClick={async () => {
                  try {
                    const token = localStorage.getItem('token');
                    const res = await fetch(`/api/v1/reports/adif?from=${from}&to=${to}`, {
                      headers: token ? { Authorization: `Bearer ${token}` } : {},
                    });
                    if (!res.ok) throw new Error();
                    const blob = await res.blob();
                    const url = URL.createObjectURL(blob);
                    const link = document.createElement('a');
                    link.href = url;
                    link.download = `BOS-ARSA_QSOs_${from}_${to}.adi`;
                    link.click();
                    URL.revokeObjectURL(url);
                  } catch {}
                }}
                className="bg-red-700 hover:bg-red-800 text-white px-4 py-2 rounded text-sm font-medium"
              >
                Download ADIF
              </button>
            </div>
            <p className="text-xs text-gray-400 mt-2">
              ADIF-Datei kann in QRZ.com, LOTW oder andere Logbuch-Software importiert werden.
            </p>
          </div>
        </>
      )}
    </div>
  );
}

