   265→  const nullBlOps = db.prepare("SELECT id, callsign FROM operators WHERE bundesland_code IS NULL").all() as { id: number; callsign: string }[];
   266→  if (nullBlOps.length > 0) {
   267→    const updateBl = db.prepare("UPDATE operators SET bundesland_code = ? WHERE id = ?");
   268→    const backfill = db.transaction(() => {
   269→      for (const op of nullBlOps) {
   270→        const code = callsignToCountryCode(op.callsign);
   271→        if (code) updateBl.run(code, op.id);
   272→      }
   273→    });
   274→    backfill();
   275→    if (nullBlOps.length > 0) console.log(`  Migration: backfilled bundesland_code for ${nullBlOps.length} operators`);
   276→  }
   277→}
