     1→import { useState, useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
     2→import { apiFetch } from '../services/api';
     3→
     4→interface Props {
     5→  value: string;
     6→  onChange: (value: string) => void;
     7→  onSelect: (operator: any) => void;
     8→  onEnter?: () => void;
     9→  autoFocus?: boolean;
    10→  className?: string;
    11→}
    12→
    13→export interface CallsignInputRef {
    14→  focus: () => void;
    15→}
    16→
    17→const CallsignInput = forwardRef<CallsignInputRef, Props>(({ value, onChange, onSelect, onEnter, autoFocus, className }, ref) => {
    18→  const [suggestions, setSuggestions] = useState<any[]>([]);
    19→  const [showSuggestions, setShowSuggestions] = useState(false);
    20→  const [selectedIdx, setSelectedIdx] = useState(-1);
    21→  const inputRef = useRef<HTMLInputElement>(null);
    22→  const debounceRef = useRef<ReturnType<typeof setTimeout>>();
    23→
    24→  useImperativeHandle(ref, () => ({
    25→    focus: () => inputRef.current?.focus(),
    26→  }));
    27→
    28→  useEffect(() => {
    29→    if (autoFocus && inputRef.current) inputRef.current.focus();
    30→  }, [autoFocus]);
    31→
    32→  const search = (q: string) => {
    33→    if (debounceRef.current) clearTimeout(debounceRef.current);
    34→    if (q.length < 1) { setSuggestions([]); setShowSuggestions(false); return; }
    35→    debounceRef.current = setTimeout(async () => {
    36→      try {
    37→        const results = await apiFetch(`/api/v1/operators?q=${encodeURIComponent(q)}`);
    38→        setSuggestions(results);
    39→        setShowSuggestions(results.length > 0);
    40→        setSelectedIdx(-1);
    41→      } catch {}
    42→    }, 150);
    43→  };
    44→
    45→  const handleChange = (val: string) => {
    46→    const upper = val.toUpperCase();
    47→    onChange(upper);
    48→    search(upper);
    49→  };
    50→
    51→  const handleKeyDown = (e: React.KeyboardEvent) => {
    52→    if (e.key === 'ArrowDown') {
    53→      e.preventDefault();
    54→      setSelectedIdx(prev => Math.min(prev + 1, suggestions.length - 1));
    55→    } else if (e.key === 'ArrowUp') {
    56→      e.preventDefault();
    57→      setSelectedIdx(prev => Math.max(prev - 1, -1));
    58→    } else if (e.key === 'Enter') {
    59→      e.preventDefault();
    60→      if (selectedIdx >= 0) {
    61→        selectSuggestion(suggestions[selectedIdx]);
    62→      } else {
    63→        setShowSuggestions(false);
    64→        onEnter?.();
    65→      }
    66→    } else if (e.key === 'Escape') {
    67→      setShowSuggestions(false);
    68→    }
    69→    // Keyboard shortcuts
    70→    if (e.altKey && e.key >= '1' && e.key <= '9') {
    71→      e.preventDefault();
    72→      onChange(value + `5/${e.key}`);
    73→    }
    74→    if (e.ctrlKey && e.key >= '1' && e.key <= '9') {
    75→      e.preventDefault();
    76→      onChange(`OE${e.key}`);
    77→    }
    78→  };
    79→
    80→  const selectSuggestion = (op: any) => {
    81→    onChange(op.callsign);
    82→    onSelect(op);
    83→    setShowSuggestions(false);
    84→    setSuggestions([]);
    85→  };
    86→
    87→  return (
    88→    <div className="relative">
    89→      <input
    90→        ref={inputRef}
    91→        type="text"
    92→        value={value}
    93→        onChange={e => handleChange(e.target.value)}
    94→        onKeyDown={handleKeyDown}
    95→        onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
    96→        onFocus={() => { if (suggestions.length > 0) setShowSuggestions(true); }}
    97→        className={`border border-gray-300 rounded px-2 py-1 font-mono uppercase text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${className || 'w-32'}`}
    98→        placeholder="Rufzeichen"
    99→      />
   100→      {showSuggestions && (
   101→        <div className="absolute z-20 top-full left-0 mt-1 bg-white border rounded shadow-lg max-h-48 overflow-auto w-64 max-w-[calc(100vw-2rem)]">
   102→          {suggestions.map((op, i) => (
   103→            <div
   104→              key={op.id}
   105→              onMouseDown={() => selectSuggestion(op)}
   106→              className={`px-3 py-1.5 cursor-pointer text-sm ${i === selectedIdx ? 'bg-blue-100' : 'hover:bg-gray-100'}`}
   107→            >
   108→              <span className="font-mono font-bold">{op.callsign}</span>
   109→              {op.name && <span className="ml-2 text-gray-500">{op.name}</span>}
   110→              {op.bezirk_code && <span className="ml-1 text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>}
   111→              {op.bundesland_name && <span className="ml-1 text-xs text-gray-400">{op.bundesland_name}</span>}
   112→              {op.total_reports > 0 && <span className="ml-auto text-xs text-blue-500">{op.total_reports} Rap.</span>}
   113→            </div>
   114→          ))}
   115→        </div>
   116→      )}
   117→    </div>
   118→  );
   119→});
   120→
   121→export default CallsignInput;
   122→

